;===================================================================================================
; Just increment the INIDISP mirror until it's at max brightness
; then move on to the next step
;===================================================================================================
Module0E_03_02_BrightenMap:
|18BC00| INC.b $13

|18BC02| LDA.b $13
|18BC04| CMP.b #$0F
|18BC06| BNE EXIT_18BC0B

|18BC08| INC.w $0200

;---------------------------------------------------------------------------------------------------

#EXIT_18BC0B:
|18BC0B| RTL

;===================================================================================================
; Start by darkening the map
;===================================================================================================
Module0E_03_00_DarkenAndPrep:
|18BC0C| DEC.b $13 ; get to a fully darkened screen
|18BC0E| BNE EXIT_18BC0B

|18BC10| LDA.b #$03
|18BC12| STA.b $95

|18BC14| LDA.b $9B ; cache HDMA
|18BC16| STA.l $7EC229

|18BC1A| JSL EnableForceBlank

|18BC1E| INC.w $0200 ; next submodule
