|18BC28| LDA.b #$40
|18BC2A| STA.b $9D

|18BC2C| LDA.b #$80
|18BC2E| STA.b $9E

|18BC30| REP #$20 ; set Link to his map graphics

|18BC32| LDA.w #$0250
|18BC35| STA.w $0100

;---------------------------------------------------------------------------------------------------

; cache our main palette for recovery
|18BC38| LDX.b #$7E

.next_colors
|18BC3A| LDA.l $7EC500,X
|18BC3E| STA.l $7FDD80,X

|18BC42| LDA.l $7EC580,X
|18BC46| STA.l $7FDE00,X

