|18BC56| STA.l $7FDF00,X

|18BC5A| DEX
|18BC5B| DEX
|18BC5C| BPL .next_colors

;---------------------------------------------------------------------------------------------------

|18BC5E| LDA.w $011A ; cache BG shake
|18BC61| STA.l $7EC221

|18BC65| LDA.w $011C
|18BC68| STA.l $7EC223

|18BC6C| STZ.w $011A ; reset BG shake
|18BC6F| STZ.w $011C

|18BC72| LDA.b $E0 ; cache BG scrolls
|18BC74| STA.l $7EC200

|18BC78| LDA.b $E2
