|18BC7E| LDA.b $E6
|18BC80| STA.l $7EC204

|18BC84| LDA.b $E8
|18BC86| STA.l $7EC206

|18BC8A| STZ.b $E0 ; reset BG scrolls
|18BC8C| STZ.b $E2
|18BC8E| STZ.b $E4
|18BC90| STZ.b $E6
|18BC92| STZ.b $E8
|18BC94| STZ.b $EA

|18BC96| LDA.b $99 ; cache CGWSEL and CGADSUB
|18BC98| STA.l $7EC225

|18BC9C| LDA.w #$2002 ; CGWSEL = 0x02, logics off, use subscreen
|18BC9F| STA.b $99 ; CGADSUB = 0x20, colormath on CGRAM0

; fill the tilemaps with blank characters
|18BCA1| LDX.b #$00
|18BCA3| LDA.w #$0300

.tilemap_fill
|18BCA6| STA.l $7F0000,X
|18BCAA| STA.l $7F0100,X
