|18BCDE| STA.l $7F0E00,X
|18BCE2| STA.l $7F0F00,X

|18BCE6| DEX
|18BCE7| DEX
|18BCE8| BNE .tilemap_fill

;---------------------------------------------------------------------------------------------------

|18BCEA| SEP #$20

|18BCEC| LDA.b #$10 ; SFX3.10
|18BCEE| STA.w $012F

|18BCF1| LDA.b #$F2 ; SONG F2 - half volume
|18BCF3| STA.w $012C

